export interface Note {
  id: string;
  folderId: string;
  body: string;
}

export interface Folder {
  id: string;
  label: string;
  notes: Note[];
}

const blank = (value: string): boolean => value.trim().length === 0;
const copyNote = (note: Note): Note => ({ ...note });
const copyFolder = (folder: Folder): Folder => ({
  id: folder.id,
  label: folder.label,
  notes: folder.notes.map(copyNote),
});

export class NotebookIndex {
  private readonly folders: Folder[] = [];

  addFolder(folder: Folder): void {
    if (blank(folder.id) || blank(folder.label)) throw new RangeError("invalid folder");
    if (this.folders.some((item) => item.id === folder.id)) throw new RangeError("duplicate folder id");
    const knownNotes = new Set(this.folders.flatMap((item) => item.notes.map((note) => note.id)));
    const localNotes = new Set<string>();
    for (const note of folder.notes) {
      if (blank(note.id) || blank(note.body) || note.folderId !== folder.id) throw new RangeError("invalid note");
      if (knownNotes.has(note.id) || localNotes.has(note.id)) throw new RangeError("duplicate note id");
      localNotes.add(note.id);
    }
    this.folders.push(copyFolder(folder));
  }

  deleteFolder(folderId: string): boolean {
    const index = this.folders.findIndex((folder) => folder.id === folderId);
    if (index < 0) return false;
    this.folders.splice(index, 1);
    return true;
  }

  addNote(folderId: string, note: Note): void {
    const folder = this.folders.find((item) => item.id === folderId);
    if (!folder) throw new RangeError("unknown folder");
    if (blank(note.id) || blank(note.body) || note.folderId !== folderId) throw new RangeError("invalid note");
    if (this.folders.some((item) => item.notes.some((existing) => existing.id === note.id))) {
      throw new RangeError("duplicate note id");
    }
    folder.notes.push(copyNote(note));
  }

  deleteNote(noteId: string): boolean {
    for (const folder of this.folders) {
      const index = folder.notes.findIndex((note) => note.id === noteId);
      if (index >= 0) {
        folder.notes.splice(index, 1);
        return true;
      }
    }
    return false;
  }

  listFolders(): Folder[] {
    return this.folders.map(copyFolder);
  }

  notesIn(folderId: string): Note[] {
    const folder = this.folders.find((item) => item.id === folderId);
    return folder ? [...folder.notes] : [];
  }
}

