import * as S from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) throw new Error(message);
}
function throwsRange(fn: () => unknown, message: string): void {
  try { fn(); } catch (error) {
    if (error instanceof RangeError) return;
    throw new Error(`${message}: wrong error type`);
  }
  throw new Error(`${message}: expected RangeError`);
}

const index = new S.NotebookIndex();
deepEqual(index.listFolders(), [], 'initial folders are empty');
deepEqual(index.notesIn('missing'), [], 'unknown folder has no notes');

const supplied = {
  id: ' f1 ', label: ' Work ', notes: [
    { id: 'n1', folderId: ' f1 ', body: ' first ' },
    { id: 'n2', folderId: ' f1 ', body: 'second' }
  ]
};
index.addFolder(supplied as S.Folder);
supplied.label = 'changed';
supplied.notes[0].body = 'changed';
supplied.notes.push({ id: 'external', folderId: ' f1 ', body: 'external' });

let folders = index.listFolders();
equal(folders.length, 1, 'one folder added');
equal(folders[0].id, ' f1 ', 'folder id is not normalized');
equal(folders[0].label, ' Work ', 'folder label is copied and not normalized');
deepEqual(index.notesIn(' f1 ').map((note) => note.id), ['n1', 'n2'], 'initial note order');
equal(index.notesIn(' f1 ')[0].body, ' first ', 'note body is copied and not normalized');

folders[0].label = 'caller mutation';
folders[0].notes[0].body = 'caller mutation';
folders.push({ id: 'fake', label: 'fake', notes: [] });
const queriedNotes = index.notesIn(' f1 ');
queriedNotes[0].body = 'query mutation';
queriedNotes.push({ id: 'fake-note', folderId: ' f1 ', body: 'fake' });
equal(index.listFolders()[0].label, ' Work ', 'folder query is a deep copy');
equal(index.notesIn(' f1 ')[0].body, ' first ', 'note query is a deep copy');
equal(index.notesIn(' f1 ').length, 2, 'query array mutation is isolated');
assert(index.listFolders() !== index.listFolders(), 'folder arrays are newly allocated');
assert(index.listFolders()[0] !== index.listFolders()[0], 'folder objects are newly allocated');
assert(index.notesIn(' f1 ')[0] !== index.notesIn(' f1 ')[0], 'note objects are newly allocated');

const added = { id: 'n3', folderId: ' f1 ', body: 'third' };
index.addNote(' f1 ', added as S.Note);
added.body = 'changed';
deepEqual(index.notesIn(' f1 ').map((note) => note.id), ['n1', 'n2', 'n3'], 'added note order');
equal(index.notesIn(' f1 ')[2].body, 'third', 'added note is copied');

index.addFolder({ id: 'f2', label: 'Second', notes: [] } as S.Folder);
deepEqual(index.listFolders().map((folder) => folder.id), [' f1 ', 'f2'], 'folder insertion order');
throwsRange(() => index.addFolder({ id: 'f2', label: 'duplicate', notes: [] } as S.Folder), 'duplicate folder id');
throwsRange(() => index.addFolder({ id: 'f3', label: 'Third', notes: [{ id: 'n3', folderId: 'f3', body: 'duplicate' }] } as S.Folder), 'globally duplicate note id');
throwsRange(() => index.addFolder({ id: 'f3', label: 'Third', notes: [{ id: 'n4', folderId: 'wrong', body: 'body' }] } as S.Folder), 'initial note folder mismatch');
throwsRange(() => index.addFolder({ id: ' ', label: 'x', notes: [] } as S.Folder), 'blank folder id');
throwsRange(() => index.addFolder({ id: 'f3', label: '\t', notes: [] } as S.Folder), 'blank folder label');
throwsRange(() => index.addNote('missing', { id: 'n4', folderId: 'missing', body: 'body' } as S.Note), 'unknown destination');
throwsRange(() => index.addNote('f2', { id: 'n4', folderId: 'wrong', body: 'body' } as S.Note), 'added note folder mismatch');
throwsRange(() => index.addNote('f2', { id: ' ', folderId: 'f2', body: 'body' } as S.Note), 'blank note id');
throwsRange(() => index.addNote('f2', { id: 'n4', folderId: 'f2', body: '  ' } as S.Note), 'blank note body');

equal(index.deleteNote('absent'), false, 'deleting absent note returns false');
equal(index.deleteNote('n2'), true, 'deleting present note returns true');
deepEqual(index.notesIn(' f1 ').map((note) => note.id), ['n1', 'n3'], 'note deletion preserves remaining order');
equal(index.deleteFolder('absent'), false, 'deleting absent folder returns false');
equal(index.deleteFolder(' f1 '), true, 'deleting folder returns true');
deepEqual(index.listFolders().map((folder) => folder.id), ['f2'], 'folder is removed');
equal(index.deleteNote('n1'), false, 'folder deletion also deletes its notes');

